import { Page } from './types';

export interface BuildContext {
  contentDir: string;
  outputDir: string;
  templatesDir?: string;
}

export interface Plugin {
  name: string;
  setContext?(context: BuildContext): void;
  onStart?(): void;
  beforeBuild?(): void;
  onFile?(page: Page): void;
  afterBuild?(pages: Page[]): void;
  onEnd?(): void;
}

import * as fs from 'fs';
import * as path from 'path';
import { Plugin } from './plugin';

export interface SsgConfig {
  plugins?: Plugin[];
}

const DEFAULT_CONFIG_SEARCH: string[] = [
  'ssg.config.ts',
  'ssg.config.js',
];

function resolveConfig(cwd: string): string | null {
  for (const name of DEFAULT_CONFIG_SEARCH) {
    const filePath = path.join(cwd, name);
    if (fs.existsSync(filePath)) {
      return filePath;
    }
  }
  return null;
}

export function loadConfig(cwd: string = process.cwd()): SsgConfig {
  const configPath = resolveConfig(cwd);
  if (!configPath) {
    return {};
  }

  try {
    const configModule = require(configPath);
    const config: SsgConfig = configModule.default || configModule || {};
    return config;
  } catch {
    return {};
  }
}

import matter from 'gray-matter';
import { marked } from 'marked';
import { Page } from '../src/types';
import { Plugin } from '../src/plugin';

function normalizeDate(d: unknown): string | undefined {
  if (d instanceof Date) return d.toISOString().slice(0, 10);
  if (typeof d === 'string') return d;
  return undefined;
}

function normalizeTags(t: unknown): string[] | undefined {
  if (Array.isArray(t)) return t.map((v) => String(v));
  return undefined;
}

function normalizeVal(v: unknown): string | undefined {
  if (typeof v === 'string') return v;
  return undefined;
}

export class MarkdownPlugin implements Plugin {
  name = 'markdown';

  onFile(page: Page): void {
    const raw = matter(page.content);

    page.title = String(raw.data.title || page.slug);
    page.date = normalizeDate(raw.data.date);
    page.tags = normalizeTags(raw.data.tags);
    page.template = normalizeVal(raw.data.template);
    page.layout = normalizeVal(raw.data.layout);
    page.content = raw.content;
    page.html = marked.parse(raw.content) as string;
  }
}

import * as fs from 'fs';
import * as path from 'path';
import { Page } from '../src/types';
import { Plugin, BuildContext } from '../src/plugin';
import { TemplateEngine } from '../src/template-engine';
import { pageTemplate, indexTemplate } from '../src/template';

export class TemplatePlugin implements Plugin {
  name = 'template';
  private context: BuildContext | null = null;

  setContext(context: BuildContext): void {
    this.context = context;
  }

  afterBuild(pages: Page[]): void {
    const ctx = this.context;
    if (!ctx) return;

    const { outputDir, templatesDir } = ctx;

    let engine: TemplateEngine | undefined;
    if (templatesDir && fs.existsSync(templatesDir)) {
      engine = new TemplateEngine({ templatesDir: path.resolve(templatesDir) });
    }

    const absoluteOutput = path.resolve(outputDir);
    if (!fs.existsSync(absoluteOutput)) {
      fs.mkdirSync(absoluteOutput, { recursive: true });
    }

    for (const page of pages) {
      let html: string;
      if (engine) {
        const tplName = page.template || (engine.hasTemplate('default') ? 'default' : undefined);
        const lytName = page.layout || (engine.hasLayout('default') ? 'default' : undefined);
        html = engine.render(page, tplName, lytName);
      } else {
        html = pageTemplate(page);
      }
      fs.writeFileSync(path.join(absoluteOutput, `${page.slug}.html`), html);
    }

    let indexHtml: string;
    if (engine && engine.hasIndex()) {
      indexHtml = engine.renderIndex(pages);
    } else {
      indexHtml = indexTemplate(pages);
    }
    fs.writeFileSync(path.join(absoluteOutput, 'index.html'), indexHtml);
  }
}

import * as http from 'http';
import * as fs from 'fs';
import * as path from 'path';
import { WebSocketServer, WebSocket } from 'ws';
import * as chokidar from 'chokidar';
import { Page } from '../src/types';
import { Plugin, BuildContext } from '../src/plugin';
import { build } from '../src/build';

function getReloadScript(): string {
  return `<script>
(function() {
  var ws = new WebSocket('ws://' + location.host);
  ws.onmessage = function(msg) {
    if (msg.data === 'reload') {
      location.reload();
    }
  };
})();
</script>`;
}

export function injectReloadScript(html: string): string {
  const script = getReloadScript();
  if (html.includes('</body>')) {
    return html.replace('</body>', script + '</body>');
  }
  if (html.includes('</html>')) {
    return html.replace('</html>', script + '</html>');
  }
  return html + script;
}

export class DevServerPlugin implements Plugin {
  name = 'dev-server';

  private context: BuildContext | null = null;
  private server: http.Server | null = null;
  private wss: WebSocketServer | null = null;
  private watcher: ReturnType<typeof chokidar.watch> | null = null;
  private connectedClients: Set<WebSocket> = new Set();

  setContext(context: BuildContext): void {
    this.context = context;
  }

  onStart(): void {
    const ctx = this.context;
    if (!ctx) return;

    const contentDir = ctx.contentDir;
    const outputDir = ctx.outputDir;
    const templatesDir = ctx.templatesDir || './templates';

    this.watcher = chokidar.watch([contentDir, templatesDir], {
      ignoreInitial: true,
    });

    this.wss = new WebSocketServer({ noServer: true });

    const mimeTypes: Record<string, string> = {
      '.html': 'text/html',
      '.css': 'text/css',
      '.js': 'application/javascript',
      '.json': 'application/json',
      '.png': 'image/png',
      '.jpg': 'image/jpeg',
      '.svg': 'image/svg+xml',
    };

    this.server = http.createServer((req, res) => {
      const url = req.url || '/';
      const filePath = url === '/' ? '/index.html' : url;
      const fullPath = path.join(path.resolve(outputDir), filePath);

      if (!fs.existsSync(fullPath)) {
        res.writeHead(404, { 'Content-Type': 'text/plain' });
        res.end('Not Found');
        return;
      }

      let content = fs.readFileSync(fullPath, 'utf-8');

      if (fullPath.endsWith('.html')) {
        content = injectReloadScript(content);
      }

      const ext = path.extname(fullPath).toLowerCase();
      const contentType = mimeTypes[ext] || 'application/octet-stream';

      res.writeHead(200, { 'Content-Type': contentType });
      res.end(content);
    });

    this.server.on('upgrade', (request, socket, head) => {
      if (this.wss) {
        this.wss.handleUpgrade(request, socket, head, (ws) => {
          this.wss!.emit('connection', ws, request);
        });
      }
    });

    if (this.wss) {
      this.wss.on('connection', (ws) => {
        this.connectedClients.add(ws);
        ws.on('close', () => {
          this.connectedClients.delete(ws);
        });
      });
    }

    if (this.watcher) {
      const handleChange = (filePath: string) => {
        console.log(`File changed: ${filePath}`);
        try {
          build(ctx.contentDir, ctx.outputDir, ctx.templatesDir);
          console.log('Rebuild complete. Reloading clients...');
          for (const client of this.connectedClients) {
            if (client.readyState === WebSocket.OPEN) {
              client.send('reload');
            }
          }
        } catch (err) {
          const message = err instanceof Error ? err.message : String(err);
          console.error(`Rebuild error: ${message}`);
        }
      };

      this.watcher.on('change', handleChange);
    }
  }

  afterBuild(_pages: Page[]): void {
    for (const client of this.connectedClients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send('reload');
      }
    }
  }

  onEnd(): void {
    if (this.watcher) {
      this.watcher.close();
    }
    if (this.server) {
      this.server.close();
    }
  }

  listen(port: number, callback?: () => void): http.Server {
    if (this.server) {
      this.server.listen(port, () => {
        console.log(`Dev server running at http://localhost:${port}/`);
        if (callback) callback();
      });
    }
    return this.server as http.Server;
  }

  getServer(): http.Server | null {
    return this.server;
  }
}

import * as fs from 'fs';
